namespace cosmos{static std::string safeName(std::string s){for(char&c:s)if(!std::isalnum((unsigned char)c)&&c!='-'&&c!='_')c='_';return s;}static std::string esc(const std::string&s){std::string o;for(char c:s){if(c=='\\'||c=='\"')o+='\\';if(c=='\n'){o+="\\n";continue;}o+=c;}return o;}bool saveWorld(const std::filesystem::path&dir,const Simulation&sim){std::filesystem::create_directories(dir);std::ofstream o(dir/(safeName(sim.planet.name)+".world"));if(!o)return false;o<<std::setprecision(17)<<"biosphere="<<sim.world.biosphere<<"\nstorm="<<sim.world.storm<<"\nanomalies="<<sim.world.anomalies<<"\ncycles="<<sim.world.cycles<<"\nlifeEvents="<<sim.world.lifeEvents<<"\nglobalEvolution="<<sim.world.globalEvolution<<"\n";for(auto&p:sim.world.outposts)o<<"outpost="<<p.x<<","<<p.z<<","<<p.createdMs<<"\n";return true;}bool loadWorld(const std::filesystem::path&dir,Simulation&sim){std::ifstream in(dir/(safeName(sim.planet.name)+".world"));if(!in)return false;sim.world=WorldState{};std::string l;while(std::getline(in,l)){auto p=l.find('=');if(p==std::string::npos)continue;auto k=l.substr(0,p),v=l.substr(p+1);try{if(k=="biosphere")sim.world.biosphere=std::stod(v);else if(k=="storm")sim.world.storm=std::stod(v);else if(k=="anomalies")sim.world.anomalies=std::stoi(v);else if(k=="cycles")sim.world.cycles=std::stod(v);else if(k=="lifeEvents")sim.world.lifeEvents=std::stoi(v);else if(k=="globalEvolution")sim.world.globalEvolution=std::stod(v);else if(k=="outpost"){std::stringstream ss(v);std::string a,b,c;std::getline(ss,a,',');std::getline(ss,b,',');std::getline(ss,c,',');sim.world.outposts.push_back({std::stod(a),std::stod(b),std::stoll(c)});}}catch(...){}}return true;}void appendLedger(const std::filesystem::path&file,const std::string&type,const std::string&text,const Simulation&sim){std::filesystem::create_directories(file.parent_path());auto now=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();std::ofstream o(file,std::ios::app);o<<"{\"t\":"<<now<<",\"type\":\""<<esc(type)<<"\",\"text\":\""<<esc(text)<<"\",\"planet\":\""<<esc(sim.planet.name)<<"\",\"x\":"<<sim.player.x<<",\"z\":"<<sim.player.z<<",\"biosphere\":"<<sim.world.biosphere<<",\"anomalies\":"<<sim.world.anomalies<<"}\n";}}
